{"command": "cd /tmp/sv-3e89c5b0be0c407286d90e36a34869c3 && \
# Find actual function symbols (type T/t) surrounding these addresses
readelf -sW libmonosgen-2.0.so.debug 2>/dev/null | awk '
$4 == "FUNC" && $2 ~ /^[0-9a-f]+$/ && $3+0 > 0 {
  start = strtonum("0x"$2)
  size = $3+0
  name = $NF
  if (start <= 0x2f4b20 && start+size > 0x2f4b20) print "0x2f4b20 -> " name " (func at 0x" sprintf("%x",start) ", size " size ")"
  if (start <= 0x2f4c84 && start+size > 0x2f4c84) print "0x2f4c84 -> " name " (func at 0x" sprintf("%x",start) ", size " size ")"
}' | head -10", "description": "Find function symbols for SGen worker"}
